/* Auto-generated listening configs for ENGLISH_BOOK. Do not edit by hand. */
window.PRACTICE_EXTRA = Object.assign(window.PRACTICE_EXTRA || {}, {"au1":{"caption":{"zh":"听咖啡馆点单对话,先答题再点「显示原文」核对。","en":"A café ordering dialogue — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段咖啡馆里的点单对话,然后回答下面的问题。","en":"Listen to a conversation at a café, then answer the questions below."},"lines":[{"who":"A","en":"Hi there! What can I get for you today?","zh":"你好!今天想喝点什么?"},{"who":"B","en":"Could I get a medium latte, please?","zh":"我要一杯中杯拿铁,谢谢。"},{"who":"A","en":"Sure. Would you like that hot or iced?","zh":"好的。要热的还是冰的?"},{"who":"B","en":"Iced, please. And could you make it with oat milk?","zh":"冰的,谢谢。能换成燕麦奶吗?"},{"who":"A","en":"Of course. Anything to eat with that?","zh":"当然。要不要配点吃的?"},{"who":"B","en":"Is the blueberry muffin fresh today?","zh":"蓝莓马芬今天新鲜吗?"},{"who":"A","en":"It came out of the oven about an hour ago.","zh":"大约一小时前刚出炉。"},{"who":"B","en":"Perfect, I'll take one. For here, please.","zh":"太好了,来一个。堂食,谢谢。"},{"who":"A","en":"That comes to five ninety. Can I get a name for the order?","zh":"一共 5.90 美元。点单用什么名字?"},{"who":"B","en":"It's Maya — that's M-A-Y-A.","zh":"叫 Maya——M-A-Y-A。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What exactly does the customer order to drink?","en":"What exactly does the customer order to drink?"},"options":["An iced latte with oat milk","A hot latte with normal milk","A cup of green tea","An iced mocha"],"correct":0,"feedback":{"zh":"她要 medium latte,iced,oat milk → 冰燕麦奶拿铁。","en":"Medium latte, iced, with oat milk."}},{"type":"mc","prompt":{"zh":"What does the customer decide to eat?","en":"What does the customer decide to eat?"},"options":["A croissant","A chocolate cookie","A blueberry muffin","Nothing at all"],"correct":2,"feedback":{"zh":"她问蓝莓马芬是否新鲜,然后说「I'll take one」。","en":"She takes the blueberry muffin."}},{"type":"mc","prompt":{"zh":"Why does the barista say the muffin is a good choice?","en":"Why does the barista say the muffin is a good choice?"},"options":["It is on special offer","It is the last one left","It has no sugar","It is fresh — baked about an hour ago"],"correct":3,"feedback":{"zh":"\"came out of the oven about an hour ago\" = 刚出炉、新鲜。","en":"It was baked about an hour ago."}},{"type":"mc","prompt":{"zh":"Will the customer eat in or take the order away?","en":"Will the customer eat in or take the order away?"},"options":["Eat in — she says \"for here\"","Take it away","Have it delivered","She hasn't decided"],"correct":0,"feedback":{"zh":"\"For here\" = 堂食(相对 to go 外带)。","en":"\"For here\" means eat in."}},{"type":"mc","prompt":{"zh":"How much does the order cost?","en":"How much does the order cost?"},"options":["$5.09","$9.50","$15.90","$5.90"],"correct":3,"feedback":{"zh":"\"five ninety\" = $5.90。","en":"\"Five ninety\" = $5.90."}}]},"au2":{"caption":{"zh":"听一段问路对话,先答题再看原文核对路线。","en":"A dialogue about asking for directions — answer first, then check the route in the transcript."},"listening":{"intro":{"zh":"听一位游客向当地人问路的对话,记下路线和地标,然后回答问题。","en":"Listen to a lost visitor asking a local for directions. Note the route and landmarks, then answer the questions below."},"lines":[{"who":"A","en":"Excuse me, sorry to bother you. I think I'm a bit lost — could you tell me the way to the train station?","zh":"打扰一下,抱歉打扰您。我好像有点迷路了——能告诉我去火车站怎么走吗?"},{"who":"B","en":"No problem at all. It's not far from here — about a ten-minute walk.","zh":"完全没问题。离这儿不远——大概走十分钟。"},{"who":"A","en":"Oh, that's good to hear. So which way should I go?","zh":"哦,那太好了。那我该往哪边走呢?"},{"who":"B","en":"Right. Go straight down King Street until you reach the traffic lights.","zh":"好的。沿着 King Street 一直走,直到红绿灯那里。"},{"who":"A","en":"Straight down King Street, all the way to the traffic lights. Got it.","zh":"沿 King Street 一直走到红绿灯。明白了。"},{"who":"B","en":"At the lights, turn left onto Queen Street. You'll walk past a big supermarket on your left.","zh":"到红绿灯左转,拐上 Queen Street。你会经过左手边一家大超市。"},{"who":"A","en":"Okay — left at the lights, then past the supermarket.","zh":"好——在红绿灯左转,然后经过那家超市。"},{"who":"B","en":"Exactly. Keep going until you come to a roundabout, and take the second exit.","zh":"没错。继续走,直到一个环岛,走第二个出口。"},{"who":"A","en":"The second exit at the roundabout. And then where is it?","zh":"在环岛走第二个出口。然后它在哪儿呢?"},{"who":"B","en":"The station is right there on your right, next to a red-brick post office. You can't miss it.","zh":"火车站就在你右手边,挨着一家红砖邮局。你肯定能找到。"},{"who":"A","en":"That's really helpful. Thank you so much for your help!","zh":"真是太有帮助了。非常感谢您的帮忙!"},{"who":"B","en":"You're very welcome. Have a safe trip!","zh":"不客气。一路平安!"}]},"quiz":[{"type":"mc","prompt":{"zh":"Where does the visitor want to go?","en":"Where does the visitor want to go?"},"options":["The airport","The train station","The bus stop","The city museum"],"correct":1,"feedback":{"zh":"游客一开始就说要去 the train station(火车站)。","en":"The visitor asks for the way to the train station."}},{"type":"mc","prompt":{"zh":"How long does the local say the walk will take?","en":"How long does the local say the walk will take?"},"options":["About two minutes","About five minutes","About ten minutes","About twenty minutes"],"correct":2,"feedback":{"zh":"当地人说 \"about a ten-minute walk\" = 大约走十分钟。","en":"He says it's about a ten-minute walk."}},{"type":"mc","prompt":{"zh":"What should the visitor do at the traffic lights?","en":"What should the visitor do at the traffic lights?"},"options":["Turn left onto Queen Street","Turn right onto Queen Street","Keep going straight ahead","Cross the road and go back"],"correct":0,"feedback":{"zh":"\"At the lights, turn left onto Queen Street\" = 红绿灯处左转。","en":"Turn left onto Queen Street at the lights."}},{"type":"mc","prompt":{"zh":"What should the visitor do at the roundabout?","en":"What should the visitor do at the roundabout?"},"options":["Take the first exit","Take the second exit","Take the third exit","Go all the way around"],"correct":1,"feedback":{"zh":"\"take the second exit\" = 走第二个出口。","en":"Take the second exit at the roundabout."}},{"type":"mc","prompt":{"zh":"What is the train station next to?","en":"What is the train station next to?"},"options":["A blue supermarket","A green city park","A large car park","A red-brick post office"],"correct":3,"feedback":{"zh":"车站 \"next to a red-brick post office\" = 挨着一家红砖邮局。","en":"It's next to a red-brick post office."}}]},"au3":{"caption":{"zh":"听一段诊所语音留言,抓住新的日期、时间和回电号码。","en":"A voicemail from a clinic — catch the new date, time, and callback number."},"listening":{"intro":{"zh":"听一段电话语音留言(牙科诊所改约),记下关键信息后回答问题。","en":"Listen to a phone voicemail from a dental clinic changing an appointment. Note the key details, then answer the questions below."},"lines":[{"en":"Hello, this is a message for Mr. Daniel Brooks.","zh":"您好,这是给 Daniel Brooks 先生的留言。"},{"en":"This is Sarah calling from the Greenfield Dental Clinic.","zh":"我是 Greenfield 牙科诊所的 Sarah。"},{"en":"I'm calling about your check-up appointment, which was booked for this Thursday.","zh":"我打来是关于您预约在本周四的检查。"},{"en":"Unfortunately, the dentist is not available that day, so we need to move your appointment.","zh":"很不巧,牙医那天没空,所以我们需要给您改期。"},{"en":"We'd like to reschedule it for Monday, the fifteenth of September, at half past two in the afternoon.","zh":"我们想把它改到 9 月 15 日(周一)下午两点半。"},{"en":"If that time doesn't suit you, please give us a call back and we'll arrange another one.","zh":"如果那个时间您不方便,请给我们回电,我们再另约。"},{"en":"Our number is 0-1-6-3-5, 5-5-0-2-9-8.","zh":"我们的电话是 0-1-6-3-5,5-5-0-2-9-8。"},{"en":"Also, please remember to bring your insurance card with you.","zh":"另外,请记得带上您的保险卡。"},{"en":"And it really helps if you arrive about ten minutes early to fill in a short form.","zh":"如果您能提前大约十分钟到,填一张简短的表格,那就再好不过了。"},{"en":"Thank you, and we look forward to seeing you. Goodbye.","zh":"谢谢,我们期待与您见面。再见。"}]},"quiz":[{"type":"mc","prompt":{"zh":"Who is the voicemail message for?","en":"Who is the voicemail message for?"},"options":["Mr. David Brooks","Mr. Daniel Brooks","Ms. Sarah Green","Dr. Greenfield"],"correct":1,"feedback":{"zh":"开头说 \"a message for Mr. Daniel Brooks\";Sarah 是打电话的人。","en":"The message is for Mr. Daniel Brooks; Sarah is the caller."}},{"type":"mc","prompt":{"zh":"Why is the clinic calling?","en":"Why is the clinic calling?"},"options":["To confirm the original Thursday time","To cancel the appointment for good","To ask him to pay a bill","To move the appointment to another day"],"correct":3,"feedback":{"zh":"牙医那天没空,所以 \"we need to move your appointment\" = 改到别的一天。","en":"The dentist isn't free, so they need to move the appointment to another day."}},{"type":"mc","prompt":{"zh":"What is the NEW date and time of the appointment?","en":"What is the NEW date and time of the appointment?"},"options":["Thursday at 2:30 pm","Monday, 15 September, at 2:30 pm","Monday, 5 September, at 3:30 pm","Friday, 15 September, at 2:00 pm"],"correct":1,"feedback":{"zh":"\"Monday, the fifteenth of September, at half past two\" = 9 月 15 日周一下午 2:30。","en":"Monday, 15 September, at half past two (2:30 pm)."}},{"type":"mc","prompt":{"zh":"What is the callback number?","en":"What is the callback number?"},"options":["01635 550298","01653 550289","01635 505298","01636 550298"],"correct":0,"feedback":{"zh":"号码是 0-1-6-3-5,5-5-0-2-9-8 = 01635 550298。","en":"The number is 01635 550298."}},{"type":"mc","prompt":{"zh":"What are you asked to do before the appointment?","en":"What are you asked to do before the appointment?"},"options":["Bring a passport and pay a deposit","Bring nothing and just turn up on time","Bring your insurance card and arrive about ten minutes early","Bring a form the clinic posted to you"],"correct":2,"feedback":{"zh":"留言让你带保险卡,并提前大约十分钟到填表。","en":"Bring your insurance card and arrive about ten minutes early to fill in a form."}}]},"au4":{"caption":{"zh":"听两则机场/车站广播,抓住航班、登机口、时间与延误信息。","en":"Two airport/station announcements — catch the flight, gate, time and delay."},"listening":{"intro":{"zh":"听两则公共广播(一则机场、一则火车站),然后回答下面的问题。","en":"Listen to two public-address announcements — one at an airport and one at a train station — then answer the questions below."},"lines":[{"en":"Good afternoon, passengers. This is the final call for British Airways flight BA 249 to Madrid.","zh":"各位旅客下午好。这是英国航空 BA 249 次飞往马德里航班的最后一次登机广播。"},{"en":"The flight is now boarding at gate 32, and the gate will close at 2:20 this afternoon.","zh":"该航班现在正在 32 号登机口登机,登机口将于今天下午 2:20 关闭。"},{"en":"Please note that the gate has changed from gate 15 to gate 32, so please make your way there straight away.","zh":"请注意,登机口已由 15 号变更为 32 号,请立即前往。"},{"en":"Any passengers who are not on board by the closing time may not be able to travel.","zh":"在关闭时间之前尚未登机的旅客可能将无法乘坐本次航班。"},{"en":"Attention, please, on platform 4.","zh":"请 4 号站台的旅客注意。"},{"en":"We are sorry to announce that the 3:05 train to Manchester Piccadilly is delayed by 20 minutes.","zh":"我们很抱歉地通知,3:05 开往曼彻斯特皮卡迪利站的列车晚点 20 分钟。"},{"en":"The train will now depart from platform 4 at approximately 3:25 this afternoon.","zh":"该列车现将于今天下午约 3:25 从 4 号站台发车。"},{"en":"This delay is due to a signalling problem earlier on the line, and we apologise for any inconvenience.","zh":"本次晚点是由于此前线路上的信号故障造成的,给您带来不便,我们深表歉意。"},{"en":"Please check the departure boards for the latest information, and listen for further announcements.","zh":"请查看出发信息屏获取最新信息,并留意后续广播。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What is the flight number of the flight to Madrid?","en":"What is the flight number of the flight to Madrid?"},"options":["BA 149","BA 249","BA 429","BA 924"],"correct":1,"feedback":{"zh":"广播里说的是 British Airways flight BA 249 to Madrid。","en":"The announcement says British Airways flight BA 249 to Madrid."}},{"type":"mc","prompt":{"zh":"Which gate is the Madrid flight boarding from now?","en":"Which gate is the Madrid flight boarding from now?"},"options":["Gate 15","Gate 23","Gate 32","Gate 12"],"correct":2,"feedback":{"zh":"登机口已从 15 号改到 32 号,现在是 gate 32。","en":"The gate changed from 15 to 32, so it is now gate 32."}},{"type":"mc","prompt":{"zh":"By what time must passengers be on board the Madrid flight?","en":"By what time must passengers be on board the Madrid flight?"},"options":["2:20 in the afternoon","3:25 in the afternoon","3:05 in the afternoon","2:15 in the afternoon"],"correct":0,"feedback":{"zh":"广播说 the gate will close at 2:20 this afternoon(2:20 关闭)。","en":"The gate closes at 2:20 in the afternoon."}},{"type":"mc","prompt":{"zh":"What is the problem with the train to Manchester Piccadilly?","en":"What is the problem with the train to Manchester Piccadilly?"},"options":["It has been cancelled","It is delayed by 20 minutes","It is delayed by 15 minutes","It has changed platforms"],"correct":1,"feedback":{"zh":"列车 delayed by 20 minutes,即晚点 20 分钟。","en":"The train is delayed by 20 minutes."}},{"type":"mc","prompt":{"zh":"Why is the train delayed?","en":"Why is the train delayed?"},"options":["Because of bad weather","Because of a staff shortage","Because of an earlier accident","Because of a signalling problem"],"correct":3,"feedback":{"zh":"原因是 a signalling problem(信号故障)。","en":"The delay is due to a signalling problem."}}]},"au5":{"caption":{"zh":"听一段求职面试对话,抓住经历、优势、行为面试题与到岗时间。","en":"A job interview — catch the experience, strength, behavioural question and start date."},"listening":{"intro":{"zh":"听一段求职面试对话(A 是面试官,B 是应聘者),然后回答下面的问题。","en":"Listen to a job interview — A is the interviewer and B is the candidate — then answer the questions below."},"lines":[{"who":"A","en":"Thanks for coming in today. To start, could you tell me a little about your background?","zh":"感谢你今天前来。首先,能简单介绍一下你的经历吗?"},{"who":"B","en":"Of course. I've worked as a marketing assistant for the past three years at a small online shop.","zh":"当然。过去三年我在一家小型网店做市场营销助理。"},{"who":"A","en":"Great. And what would you say is your biggest strength?","zh":"很好。那你觉得自己最大的优势是什么?"},{"who":"B","en":"I'd say I'm very organised. For example, last year I ran all our email campaigns and kept every launch on schedule.","zh":"我会说我做事很有条理。比如去年我负责所有邮件营销活动,让每次上线都按计划准时进行。"},{"who":"A","en":"That's good to hear. Can you tell me about a time you had to deal with a difficult problem at work?","zh":"这很不错。能讲一次你在工作中不得不处理棘手问题的经历吗?"},{"who":"B","en":"Sure. Once a product launch was nearly delayed because a supplier let us down, so I found a backup supplier in two days and we launched on time.","zh":"好的。有一次因为供应商出了问题,产品上线差点被推迟,于是我两天内找到了备用供应商,我们按时上线了。"},{"who":"A","en":"That's impressive. How do you usually handle tight deadlines?","zh":"很了不起。你通常怎么应对紧迫的截止期限?"},{"who":"B","en":"I break big tasks into smaller steps and check my progress every day, so nothing is left to the last minute.","zh":"我会把大任务拆成小步骤,每天检查进度,这样就不会把事情拖到最后一刻。"},{"who":"A","en":"Perfect. If we offered you the role, when would you be able to start?","zh":"很好。如果我们给你这个职位,你什么时候能到岗?"},{"who":"B","en":"I'd need to give my current employer two weeks' notice, so I could start on the first of September.","zh":"我需要向现在的雇主提前两周通知,所以我可以在九月一日入职。"},{"who":"A","en":"That works well for us. Do you have any questions for me?","zh":"这对我们很合适。你有什么想问我的吗?"},{"who":"B","en":"Yes — could you tell me what a typical day in this team looks like?","zh":"有的——能跟我说说这个团队一天通常是怎样的吗?"},{"who":"A","en":"Absolutely. Let's go through that now, and we'll be in touch by the end of the week.","zh":"当然可以。我们现在就来聊聊,我们会在本周末之前和你联系。"}]},"quiz":[{"type":"mc","prompt":{"zh":"How long has the candidate worked as a marketing assistant?","en":"How long has the candidate worked as a marketing assistant?"},"options":["One year","Two years","Three years","Five years"],"correct":2,"feedback":{"zh":"她说 for the past three years,即三年。","en":"She says she has worked there for the past three years."}},{"type":"mc","prompt":{"zh":"What does the candidate say is her biggest strength?","en":"What does the candidate say is her biggest strength?"},"options":["She is very organised","She is very creative","She is good at public speaking","She speaks three languages"],"correct":0,"feedback":{"zh":"她说 I'm very organised(很有条理)。","en":"She says she is very organised."}},{"type":"mc","prompt":{"zh":"How did the candidate deal with the supplier problem?","en":"How did the candidate deal with the supplier problem?"},"options":["She delayed the launch","She cancelled the product","She asked her manager for help","She found a backup supplier in two days"],"correct":3,"feedback":{"zh":"她 found a backup supplier in two days,两天内找到备用供应商。","en":"She found a backup supplier in two days."}},{"type":"mc","prompt":{"zh":"When could the candidate start the new job?","en":"When could the candidate start the new job?"},"options":["Immediately","On the first of September","In three weeks","At the end of the week"],"correct":1,"feedback":{"zh":"她要提前两周通知,能在 the first of September(九月一日)入职。","en":"After two weeks' notice, she could start on the first of September."}},{"type":"mc","prompt":{"zh":"What does the interviewer say will happen next?","en":"What does the interviewer say will happen next?"},"options":["They will offer her the job on the spot","She must take a written test","They will be in touch by the end of the week","She should call back next month"],"correct":2,"feedback":{"zh":"面试官说 we'll be in touch by the end of the week(本周末前联系)。","en":"The interviewer says they will be in touch by the end of the week."}}]},"au6":{"caption":{"zh":"听一段关于蜂蜜如何酿成的科普短讲,先答题再点「显示原文」核对。","en":"A short talk on how honey is made — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段关于蜜蜂如何酿造蜂蜜的短讲,然后回答下面的问题。","en":"Listen to a short talk about how bees make honey, then answer the questions below."},"lines":[{"en":"Have you ever wondered how bees turn flowers into the sweet honey on your toast?","zh":"你有没有想过,蜜蜂是怎么把花变成你面包上那甜甜的蜂蜜的?"},{"en":"It all starts when a worker bee flies from flower to flower, collecting a sugary liquid called nectar.","zh":"一切都始于一只工蜂在花丛间飞来飞去,采集一种叫花蜜的含糖液体。"},{"en":"She stores the nectar in a special part of her body, sometimes called a 'honey stomach', and carries it back to the hive.","zh":"她把花蜜储存在身体里一个特殊的地方——有时叫「蜜胃」——然后带回蜂巢。"},{"en":"Back home, she passes the nectar to other bees, who add natural chemicals called enzymes that slowly change the sugars.","zh":"回到家后,她把花蜜传给其他蜜蜂,它们会加入一种叫酶的天然物质,慢慢改变其中的糖分。"},{"en":"Then the bees spread the liquid across the honeycomb and fan it with their wings to dry it out.","zh":"然后蜜蜂把这些液体铺在巢脾上,用翅膀扇风,把水分吹干。"},{"en":"This fanning removes most of the water, until the thin nectar becomes thick, sticky honey.","zh":"这样的扇风会带走大部分水分,直到稀薄的花蜜变成浓稠黏腻的蜂蜜。"},{"en":"To fill just one small jar, bees may have to visit more than a million flowers.","zh":"仅仅装满一小罐蜂蜜,蜜蜂可能要拜访一百多万朵花。"},{"en":"When the honey is ready, the bees seal each cell with a thin cap of wax to keep it fresh for the winter.","zh":"蜂蜜做好后,蜜蜂会用一层薄薄的蜡把每个蜂房封住,让它在冬天保持新鲜。"},{"en":"Because honey has so little water and is naturally acidic, it almost never goes bad.","zh":"由于蜂蜜含水极少又天然呈酸性,它几乎永远不会变质。"},{"en":"In fact, jars of honey found in ancient tombs were still good to eat thousands of years later.","zh":"事实上,在古墓里发现的蜂蜜,几千年后依然可以食用。"},{"en":"So the next time you taste honey, remember it is really the hard work of thousands of tiny bees.","zh":"所以下次你尝到蜂蜜时,记住:那其实是成千上万只小蜜蜂辛勤劳动的成果。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What is the talk mainly about?","en":"What is the talk mainly about?"},"options":["How to start beekeeping at home","How bees turn nectar into honey","Why bees are disappearing","How flowers grow in spring"],"correct":1,"feedback":{"zh":"全篇围绕蜜蜂如何把花蜜变成蜂蜜,是主旨。","en":"The whole talk explains how bees turn nectar into honey."}},{"type":"mc","prompt":{"zh":"Where does a worker bee first store the nectar she collects?","en":"Where does a worker bee first store the nectar she collects?"},"options":["In the honeycomb","In a bag on her legs","In a wax cup","In a special 'honey stomach'"],"correct":3,"feedback":{"zh":"讲到她把花蜜存在身体里一个特殊的地方,叫「honey stomach 蜜胃」。","en":"She keeps it in a special part of her body, a 'honey stomach'."}},{"type":"mc","prompt":{"zh":"Why do the bees fan the nectar with their wings?","en":"Why do the bees fan the nectar with their wings?"},"options":["To remove most of the water","To keep the hive warm","To call other bees over","To cool the honey down for eating"],"correct":0,"feedback":{"zh":"扇翅膀是为了「dry it out」,带走大部分水分。","en":"Fanning dries the nectar by removing most of the water."}},{"type":"mc","prompt":{"zh":"About how many flowers might bees visit to fill one small jar of honey?","en":"About how many flowers might bees visit to fill one small jar of honey?"},"options":["About a hundred","About a thousand","More than a million","Exactly ten thousand"],"correct":2,"feedback":{"zh":"原文说「more than a million flowers」——一百多万朵。","en":"The talk says more than a million flowers for one small jar."}},{"type":"mc","prompt":{"zh":"What does the example of honey found in ancient tombs suggest?","en":"What does the example of honey found in ancient tombs suggest?"},"options":["Honey must be eaten within a week","Honey was only made long ago","Ancient people disliked honey","Honey can last for thousands of years without spoiling"],"correct":3,"feedback":{"zh":"古墓蜂蜜几千年后仍可食用,说明蜂蜜能保存极久、几乎不坏。","en":"It shows honey can survive for thousands of years without going bad."}}]},"au7":{"caption":{"zh":"听酒店前台办理入住对话,先答题再点「显示原文」核对。","en":"A hotel check-in dialogue — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段在酒店前台办理入住的对话,然后回答下面的问题。","en":"Listen to a guest checking in at a hotel reception, then answer the questions below."},"lines":[{"who":"A","en":"Good afternoon, and welcome to the Riverside Hotel. How can I help you?","zh":"下午好,欢迎入住河景酒店。有什么可以帮您?"},{"who":"B","en":"Hi, I have a reservation under the name Daniel Foster.","zh":"你好,我有预订,名字是 Daniel Foster。"},{"who":"A","en":"Let me check for you... Yes, Mr. Foster, I have you down for three nights, checking out on Friday.","zh":"我帮您查一下……有的,Foster 先生,您订了三晚,周五退房。"},{"who":"B","en":"That's right. I think I booked a double room.","zh":"对。我记得订的是大床房。"},{"who":"A","en":"Actually, the reservation is for a twin room — that's two single beds. Shall I keep it, or change it to a double?","zh":"其实预订上是双床房——两张单人床。要保留,还是帮您换成大床房?"},{"who":"B","en":"A twin is fine, thanks. Two beds actually suits us better.","zh":"双床就行,谢谢。两张床其实更合适我们。"},{"who":"A","en":"Great. Could I see your passport, please? ... Thank you.","zh":"好的。可以看一下您的护照吗?……谢谢。"},{"who":"B","en":"Sure. Oh, and what time is breakfast?","zh":"给您。对了,早餐几点?"},{"who":"A","en":"Breakfast is served from seven to ten in the morning, in the restaurant on the ground floor.","zh":"早餐上午七点到十点,在一楼的餐厅。"},{"who":"B","en":"Perfect. And is there wifi in the room?","zh":"很好。房间里有无线网吗?"},{"who":"A","en":"Yes. The network is 'Riverside Guest', and the password is your room number, 412.","zh":"有的。网络名是「Riverside Guest」,密码就是您的房号 412。"},{"who":"B","en":"Got it. And what time do we need to check out?","zh":"明白了。那我们几点退房?"},{"who":"A","en":"Checkout is at eleven. Here's your key card — the lift is just around the corner. Enjoy your stay!","zh":"退房时间是十一点。这是您的房卡——电梯就在拐角处。祝您入住愉快!"},{"who":"B","en":"Thank you very much.","zh":"非常感谢。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What name is the reservation under?","en":"What name is the reservation under?"},"options":["Daniel Porter","Daniel Foster","David Foster","Danny Ford"],"correct":1,"feedback":{"zh":"预订名字是 Daniel Foster。","en":"The reservation is under Daniel Foster."}},{"type":"mc","prompt":{"zh":"How many nights is the guest staying?","en":"How many nights is the guest staying?"},"options":["Two nights","One night","Three nights","Four nights"],"correct":2,"feedback":{"zh":"前台确认「three nights」,周五退房。","en":"Three nights, checking out on Friday."}},{"type":"mc","prompt":{"zh":"What kind of room does the guest actually take?","en":"What kind of room does the guest actually take?"},"options":["A twin room with two single beds","A double room with one big bed","A single room","A family suite"],"correct":0,"feedback":{"zh":"预订是 twin room(两张单人床),客人决定保留。","en":"A twin room (two single beds), which the guest keeps."}},{"type":"mc","prompt":{"zh":"When and where is breakfast served?","en":"When and where is breakfast served?"},"options":["6 to 9, by the pool","8 to 11, on the top floor","7 to 9, in the room","7 to 10, in the ground-floor restaurant"],"correct":3,"feedback":{"zh":"早餐 7:00–10:00,在一楼餐厅。","en":"Breakfast is 7 to 10, in the ground-floor restaurant."}},{"type":"mc","prompt":{"zh":"What is the wifi password?","en":"What is the wifi password?"},"options":["The guest's last name","The room number, 412","The word 'riverside'","There is no wifi in the rooms"],"correct":1,"feedback":{"zh":"密码就是房号 412。","en":"The password is the room number, 412."}}]},"au8":{"caption":{"zh":"听看医生(全科门诊)的问诊对话,先答题再点「显示原文」核对。","en":"A visit to the doctor — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段病人向全科医生(GP)描述症状、医生给出建议的对话,然后回答下面的问题。","en":"Listen to a patient describing symptoms to a GP, then answer the questions below."},"lines":[{"who":"A","en":"Hello, come in and take a seat. What seems to be the problem today?","zh":"你好,请进,请坐。今天哪里不舒服?"},{"who":"B","en":"Hi, doctor. I've had a really sore throat and a headache for the last three days.","zh":"你好,医生。我嗓子很疼,还头疼,已经三天了。"},{"who":"A","en":"I'm sorry to hear that. Have you had a fever at all?","zh":"真是难受。有没有发烧?"},{"who":"B","en":"A little. The nurse just took my temperature and it was 37.8 degrees.","zh":"有一点。护士刚给我量了体温,是 37.8 度。"},{"who":"A","en":"Okay, that's only slightly high. Are you coughing, or is it mainly your throat?","zh":"好,只是略高一点。有咳嗽吗,还是主要是嗓子?"},{"who":"B","en":"Mostly my throat. It really hurts when I swallow, especially in the morning.","zh":"主要是嗓子。吞咽的时候很疼,早上尤其明显。"},{"who":"A","en":"Let me have a quick look. Open wide and say 'ah'... Yes, it's a bit red, but nothing serious.","zh":"我看一下。张大嘴说「啊」……嗯,有点红,但没什么大碍。"},{"who":"B","en":"That's a relief. Do I need antibiotics?","zh":"那就放心了。我需要吃抗生素吗?"},{"who":"A","en":"No, I don't think so. It looks like a common cold, and that usually clears up on its own.","zh":"我看不需要。像是普通感冒,一般会自己好。"},{"who":"A","en":"Get plenty of rest, drink lots of water, and you can take paracetamol for the pain.","zh":"多休息,多喝水,疼的话可以吃点扑热息痛。"},{"who":"B","en":"How often should I take it?","zh":"多久吃一次?"},{"who":"A","en":"One or two tablets every six hours, but no more than eight in a day.","zh":"每六小时一到两片,但一天不超过八片。"},{"who":"A","en":"If you're not better in a week, or the fever gets higher, come back and see me.","zh":"如果一周内没好转,或者烧得更高,就再来找我。"},{"who":"B","en":"Thank you, doctor. I'll do that.","zh":"谢谢医生,我会的。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What are the patient's main symptoms?","en":"What are the patient's main symptoms?"},"options":["A sore throat and a headache","A stomach ache and vomiting","An earache and a rash","Back pain and dizziness"],"correct":0,"feedback":{"zh":"病人说嗓子疼加头疼。","en":"A sore throat and a headache."}},{"type":"mc","prompt":{"zh":"How long has the patient felt unwell?","en":"How long has the patient felt unwell?"},"options":["Since this morning","For three days","For two weeks","For about a month"],"correct":1,"feedback":{"zh":"「for the last three days」= 已经三天了。","en":"For the last three days."}},{"type":"mc","prompt":{"zh":"What was the patient's temperature?","en":"What was the patient's temperature?"},"options":["36.5 degrees","39.0 degrees","38.5 degrees","37.8 degrees"],"correct":3,"feedback":{"zh":"护士量的体温是 37.8 度,只是略高。","en":"37.8 degrees — only slightly high."}},{"type":"mc","prompt":{"zh":"What does the doctor think the illness probably is?","en":"What does the doctor think the illness probably is?"},"options":["Food poisoning","A serious infection needing antibiotics","A common cold","An allergy"],"correct":2,"feedback":{"zh":"医生说像普通感冒,不需要抗生素。","en":"Probably a common cold — no antibiotics needed."}},{"type":"mc","prompt":{"zh":"What does the doctor tell the patient to do?","en":"What does the doctor tell the patient to do?"},"options":["Take antibiotics for a week","Rest, drink plenty of water, and take paracetamol","Stay overnight in hospital","Stop eating for a day"],"correct":1,"feedback":{"zh":"建议:多休息、多喝水、按需吃扑热息痛;若一周不好或烧更高再来。","en":"Rest, drink water, take paracetamol; come back if it gets worse or is no better in a week."}}]},"au9":{"caption":{"zh":"听一段天气预报独白,先答题再点「显示原文」核对。","en":"A TV-style weather forecast — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段电视/广播式的天气预报,然后回答下面的问题。","en":"Listen to a friendly TV-style weather forecast, then answer the questions below."},"lines":[{"en":"Good morning, and welcome to your weather update for the whole country.","zh":"早上好,欢迎收看全国天气预报。"},{"en":"Today starts bright and sunny across most of the south, with temperatures climbing to around 24 degrees by the afternoon.","zh":"今天南部大部分地区晴朗,午后气温将升至约 24 摄氏度。"},{"en":"In the north, however, it will be much cooler, with cloud, a light breeze, and highs of just 15 degrees.","zh":"而北部会凉爽许多,多云、微风,最高气温仅 15 摄氏度。"},{"en":"There is a warning of strong winds along the south coast this evening, so please take care if you are driving.","zh":"今晚南部沿海有大风预警,开车请务必小心。"},{"en":"Heavy rain is expected to reach the north-west overnight, and it could last until dawn.","zh":"预计今夜西北部将迎来大雨,可能持续到黎明。"},{"en":"Tomorrow morning will feel colder everywhere, dropping to around 8 degrees first thing.","zh":"明天早晨各地都会更冷,清晨降到约 8 摄氏度。"},{"en":"The rain should clear by midday, leaving bright spells and the odd shower in the afternoon.","zh":"雨在中午前后应会停,午后转为时晴时阵雨。"},{"en":"Winds will ease off tomorrow, so it will feel calmer and more pleasant.","zh":"明天风力减弱,会感觉更平静宜人。"},{"en":"If you are heading out today, remember to take an umbrella and wrap up warm in the north.","zh":"如果今天要出门,记得带伞;在北部要多穿点保暖。"},{"en":"That is all from me — have a lovely day, and stay safe out there.","zh":"我的播报就到这里——祝你一天愉快,注意安全。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What kind of programme is this?","en":"What kind of programme is this?"},"options":["A traffic and travel report","A weather forecast for the country","A news report about a flood","An advert for a beach holiday"],"correct":1,"feedback":{"zh":"开头就说 welcome to your weather update,是全国天气预报。","en":"It opens with a weather update for the whole country."}},{"type":"mc","prompt":{"zh":"What will the weather be like in the south today?","en":"What will the weather be like in the south today?"},"options":["Cold with snow","Cloudy with a strong breeze","Sunny, reaching about 24 degrees","Foggy all morning"],"correct":2,"feedback":{"zh":"南部 bright and sunny,午后约 24 度。","en":"Bright and sunny, climbing to about 24 degrees."}},{"type":"mc","prompt":{"zh":"Where is there a warning of strong winds this evening?","en":"Where is there a warning of strong winds this evening?"},"options":["Along the south coast","In the north-west","In the mountains","Across the whole country"],"correct":0,"feedback":{"zh":"预警是 strong winds along the south coast this evening。","en":"Strong winds are warned along the south coast tonight."}},{"type":"mc","prompt":{"zh":"How cold will it be tomorrow morning?","en":"How cold will it be tomorrow morning?"},"options":["Around 24 degrees","Around 15 degrees","Warmer than today","Around 8 degrees"],"correct":3,"feedback":{"zh":"明早各地更冷,清晨降到约 8 度。","en":"It drops to around 8 degrees first thing tomorrow."}},{"type":"mc","prompt":{"zh":"Why does the forecaster tell people in the north to wrap up warm?","en":"Why does the forecaster tell people in the north to wrap up warm?"},"options":["Because a heatwave is coming","Because the wind will stop completely","Because the north is much cooler than the south","Because it is a public holiday"],"correct":2,"feedback":{"zh":"北部今天仅 15 度、明早约 8 度,比南部冷得多,所以要保暖。","en":"The north is much cooler (15° today, ~8° tomorrow), so people should keep warm."}}]},"au10":{"caption":{"zh":"听一段校园学习讲座独白,先答题再点「显示原文」核对。","en":"A short campus study talk — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段校园里的简短学习讲座,然后回答下面的问题。","en":"Listen to a short campus talk about studying, then answer the questions below."},"lines":[{"en":"Good afternoon, everyone, and thank you for coming to today's short study session.","zh":"大家下午好,感谢各位来参加今天的简短学习讲座。"},{"en":"I want to share one simple idea that can really improve the way you revise: spread your practice out over time instead of cramming.","zh":"我想分享一个简单却很有用的观点:把复习分散到不同时间,而不是临时突击。"},{"en":"Cramming — studying everything the night before an exam — might help you pass, but you forget most of it within a week.","zh":"突击复习——考试前一晚把所有内容一次看完——也许能让你通过考试,但一周内你会忘掉大部分。"},{"en":"When you study a little every day, your brain has to recall the information again and again, and that repeated effort makes the memory much stronger.","zh":"当你每天学一点,大脑就要一次次地回忆信息,这种反复的努力会让记忆牢固得多。"},{"en":"This method is often called spaced practice, and researchers have studied it for over a hundred years.","zh":"这种方法常被称为「间隔练习」,研究者已经研究了它一百多年。"},{"en":"It also lowers your stress, because you are not trying to learn a whole term's work in one long, tiring night.","zh":"它还能降低压力,因为你不必在一个漫长疲惫的夜晚里学完整个学期的内容。"},{"en":"For example, if you have thirty new words to learn, review six of them each day for five days rather than all thirty at once.","zh":"举个例子,如果你要学 30 个新单词,与其一次学完,不如每天复习 6 个,分五天完成。"},{"en":"By the end of the week, those words will feel familiar, and you will remember them long after the test.","zh":"到周末时,这些单词会变得熟悉,而且考试后很久你依然记得。"},{"en":"So my advice is simple: make a short study plan, and start a few weeks before your exams, not the night before.","zh":"所以我的建议很简单:制定一个简短的学习计划,在考试前几周就开始,而不是前一晚。"},{"en":"Try it with just one subject this month, and I think you will be surprised by the difference.","zh":"这个月就先用一门课试试,我想你会对效果感到惊讶。"}]},"quiz":[{"type":"mc","prompt":{"zh":"What is the speaker's main piece of advice?","en":"What is the speaker's main piece of advice?"},"options":["Study everything the night before the exam","Spread your studying out over several days or weeks","Only revise in the library","Never make a study plan"],"correct":1,"feedback":{"zh":"核心观点是把练习分散到不同时间,而不是突击。","en":"Spread your practice out over time instead of cramming."}},{"type":"mc","prompt":{"zh":"According to the speaker, what usually happens if you cram the night before an exam?","en":"According to the speaker, what usually happens if you cram the night before an exam?"},"options":["You forget most of it within a week","You remember it for years","You are guaranteed to fail","You feel no stress at all"],"correct":0,"feedback":{"zh":"突击也许能过关,但一周内就忘掉大部分。","en":"You may pass, but forget most of it within a week."}},{"type":"mc","prompt":{"zh":"Why does studying a little every day work better?","en":"Why does studying a little every day work better?"},"options":["Because teachers prefer this method","Because you can skip the hard topics","Because you spend less total time","Because your brain recalls the information again and again"],"correct":3,"feedback":{"zh":"反复回忆让记忆更牢固。","en":"Repeated recall makes the memory much stronger."}},{"type":"mc","prompt":{"zh":"In the example, how does the speaker suggest learning thirty new words?","en":"In the example, how does the speaker suggest learning thirty new words?"},"options":["Thirty words in one evening","Ten new words every hour","Six words a day over five days","Fifteen words twice a week"],"correct":2,"feedback":{"zh":"例子是每天 6 个、分五天,而不是一次学完 30 个。","en":"Six words a day for five days, not all thirty at once."}},{"type":"mc","prompt":{"zh":"Why does the speaker suggest trying the method with just one subject this month?","en":"Why does the speaker suggest trying the method with just one subject this month?"},"options":["Because the other subjects do not matter","Because it is an easy, low-risk way to see if it works","Because you only have one exam","Because one subject is enough study"],"correct":1,"feedback":{"zh":"先用一门课小范围试验,风险低、容易看出效果——属于推断。","en":"It's a small, low-risk way to test the method — an inference."}}]},"au11":{"caption":{"zh":"听一段商店退货对话,先答题再点「显示原文」核对。","en":"A shop-return dialogue — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段在服装店退货的对话,然后回答下面的问题。","en":"Listen to a conversation about returning an item at a clothes shop, then answer the questions below."},"lines":[{"who":"A","en":"Good afternoon. How can I help you today?","zh":"下午好,有什么可以帮您的吗?"},{"who":"B","en":"Hi. I'd like to return this jacket, please. I bought it last week.","zh":"你好,我想退这件夹克,谢谢。我上周买的。"},{"who":"A","en":"No problem at all. Is there something wrong with it?","zh":"完全没问题。是有什么问题吗?"},{"who":"B","en":"It's the wrong size, actually. I need a large, but this one is a medium.","zh":"其实是尺码不对。我需要大号,但这件是中号。"},{"who":"A","en":"I see. Do you have the receipt with you?","zh":"明白了。您带小票了吗?"},{"who":"B","en":"Yes, here it is. I paid forty-five pounds for it.","zh":"带了,给您。我当时付了 45 英镑。"},{"who":"A","en":"Thank you. And have you worn it at all?","zh":"谢谢。这件您穿过吗?"},{"who":"B","en":"No, it still has the tags on. I only tried it on at home.","zh":"没有,吊牌还在。我只在家里试穿了一下。"},{"who":"A","en":"Great. We can do a refund or an exchange — whichever you prefer. Our policy is returns within thirty days.","zh":"很好。我们可以退款或换货,您选哪个都行。我们的政策是 30 天内可退。"},{"who":"B","en":"I'd rather just have a refund, if that's okay. I found a similar one somewhere else.","zh":"如果可以的话,我想直接退款。我在别处找到了类似的一件。"},{"who":"A","en":"Of course. Since you paid by card, the money will go back to the same card.","zh":"当然可以。您是刷卡付的,钱会退回到同一张卡上。"},{"who":"B","en":"How long does that usually take?","zh":"这一般要多久?"},{"who":"A","en":"Around three to five working days. I'll print you a receipt for the return.","zh":"大约三到五个工作日。我给您打一张退货凭条。"},{"who":"B","en":"Perfect. Thank you very much for your help.","zh":"太好了。非常感谢您的帮助。"}]},"quiz":[{"type":"mc","prompt":{"zh":"Why is the customer returning the jacket?","en":"Why is the customer returning the jacket?"},"options":["There is a hole in it","It is the wrong size","She does not like the colour","It was too expensive"],"correct":1,"feedback":{"zh":"她说 the wrong size——需要 large,却买成了 medium。","en":"She says it is the wrong size — she needs a large, not a medium."}},{"type":"mc","prompt":{"zh":"Does the customer have the receipt?","en":"Does the customer have the receipt?"},"options":["Yes, she has it with her","No, she lost it","She left it at home","She was never given one"],"correct":0,"feedback":{"zh":"她说 \"here it is\",小票就在手上。","en":"She says \"here it is\" — the receipt is with her."}},{"type":"mc","prompt":{"zh":"How much did she pay for the jacket?","en":"How much did she pay for the jacket?"},"options":["Fifteen pounds","Fifty-four pounds","Forty-five pounds","Forty pounds"],"correct":2,"feedback":{"zh":"她说 \"forty-five pounds\" = £45。","en":"She paid forty-five pounds (£45)."}},{"type":"mc","prompt":{"zh":"Within how many days does the shop accept returns?","en":"Within how many days does the shop accept returns?"},"options":["Within 30 days","Within 14 days","Within 7 days","Within 90 days"],"correct":0,"feedback":{"zh":"店员说 \"returns within thirty days\" = 30 天内可退。","en":"The assistant says returns are accepted within thirty days."}},{"type":"mc","prompt":{"zh":"How will the customer get her money back?","en":"How will the customer get her money back?"},"options":["In cash at the till","As store credit","By cheque in the post","Back onto the card she paid with"],"correct":3,"feedback":{"zh":"她刷卡付款,钱会退回原卡(back to the same card)。","en":"She paid by card, so the refund goes back to the same card."}}]},"au12":{"caption":{"zh":"听一段本地电台新闻简报,先答题再点「显示原文」核对。","en":"A short local-radio news bulletin — answer first, then reveal the transcript."},"listening":{"intro":{"zh":"听一段虚构小镇的本地电台新闻简报,然后回答下面的问题。","en":"Listen to a short local-radio news bulletin for an imaginary town, then answer the questions below."},"lines":[{"en":"Good morning, and welcome to the nine o'clock news update here on Fernbrook Community Radio.","zh":"早上好,欢迎收听 Fernbrook 社区电台的九点新闻简讯。"},{"en":"In local news, the town's brand-new public library will open its doors on Saturday the fifteenth of March.","zh":"本地新闻方面,本镇全新的公共图书馆将于 3 月 15 日星期六正式开放。"},{"en":"The mayor will cut the ribbon at ten in the morning, and there will be free story-time sessions for children all day.","zh":"市长将在上午十点剪彩,当天全天还会为孩子们举办免费的故事会。"},{"en":"Drivers should be aware that Bridge Street will be closed for repairs from Monday until Thursday next week.","zh":"请各位司机注意,Bridge Street 将于下周一至周四因维修封闭。"},{"en":"The council is asking everyone to use Mill Lane instead, and to leave a few extra minutes for the journey.","zh":"镇政府请大家改走 Mill Lane,并为路程多留出几分钟。"},{"en":"And finally, this weekend sees the return of the Fernbrook Fun Run, in aid of the local animal shelter.","zh":"最后一条,本周末 Fernbrook 趣味跑将再度举行,为本地动物收容所募捐。"},{"en":"Runners of all ages are welcome, and the five-kilometre route starts at Riverside Park at nine on Sunday morning.","zh":"欢迎各年龄段的跑者参加,5 公里路线于周日上午九点从 Riverside Park 出发。"},{"en":"You can still sign up on the day for a small fee of five pounds, and every penny goes to help the shelter.","zh":"当天仍可现场报名,费用仅 5 英镑,所得款项将全数用于帮助收容所。"},{"en":"Now, over to the weather: it will be cloudy this morning, with sunshine and light winds expected by the afternoon.","zh":"接下来是天气:今天上午多云,预计下午转晴、微风。"},{"en":"That's all for now — stay tuned for more updates at midday.","zh":"今天的新闻就到这里——请继续锁定,中午还有更多更新。"}]},"quiz":[{"type":"mc","prompt":{"zh":"When will the new public library open?","en":"When will the new public library open?"},"options":["On Saturday the fifteenth of March","On Sunday morning","Next Monday","At midday today"],"correct":0,"feedback":{"zh":"报道说图书馆将于 3 月 15 日星期六开放。","en":"The library opens on Saturday the fifteenth of March."}},{"type":"mc","prompt":{"zh":"What time will the mayor cut the ribbon?","en":"What time will the mayor cut the ribbon?"},"options":["At nine in the morning","At ten in the morning","At midday","In the afternoon"],"correct":1,"feedback":{"zh":"\"cut the ribbon at ten in the morning\" = 上午十点剪彩。","en":"The ribbon-cutting is at ten in the morning."}},{"type":"mc","prompt":{"zh":"Which road are drivers asked to use instead of Bridge Street?","en":"Which road are drivers asked to use instead of Bridge Street?"},"options":["Riverside Park","The high street","Bridge Lane","Mill Lane"],"correct":3,"feedback":{"zh":"镇政府请大家 \"use Mill Lane instead\" = 改走 Mill Lane。","en":"The council asks everyone to use Mill Lane instead."}},{"type":"mc","prompt":{"zh":"What is the Fun Run raising money for?","en":"What is the Fun Run raising money for?"},"options":["The new library","The children's story-time","The local animal shelter","Repairs to Bridge Street"],"correct":2,"feedback":{"zh":"\"in aid of the local animal shelter\" = 为本地动物收容所募捐。","en":"It is in aid of the local animal shelter."}},{"type":"mc","prompt":{"zh":"What will the weather be like in the afternoon?","en":"What will the weather be like in the afternoon?"},"options":["Rainy and windy","Sunny with light winds","Cloudy with strong winds","Snowy and cold"],"correct":1,"feedback":{"zh":"\"sunshine and light winds expected by the afternoon\" = 下午转晴、微风。","en":"Sunshine and light winds are expected by the afternoon."}}]}});
